/**
 * Open Graph card generator.
 *
 * Every image on this site is a hand-authored SVG, and **no social crawler
 * renders an SVG `og:image`** — Facebook, X, LinkedIn and Telegram all ignore
 * it and fall back to no preview at all. So the share card has to be a raster,
 * and it is the one raster in the project.
 *
 * It is written here rather than fetched, generated by a service, or produced
 * with an image library, because the project has exactly three runtime
 * dependencies and adding `sharp` or `resvg` to draw one 1200×630 rectangle is
 * a bad trade. Node's own `zlib` is all a PNG encoder needs.
 *
 * The card is the same art direction as `generate-media.mjs` — warm cream
 * ground, a defocused saffron mass, light falling from the top-right, which is
 * the RTL reading origin — with the brand mark from `src/app/icon.svg` over
 * it. It carries no type: rendering Persian into a generated raster needs a
 * font pipeline this project does not have, and a Latin-only card for a
 * Persian brand would read worse than a clean mark.
 *
 *   node scripts/generate-og.mjs
 */
import { deflateSync } from "node:zlib";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const outDir = join(here, "..", "public", "media");
mkdirSync(outDir, { recursive: true });

/** Open Graph's expected card size. 1.91:1, which is what every consumer crops to. */
const W = 1200;
const H = 630;

/** Kept in sync with src/app/tokens.css and scripts/generate-media.mjs. */
const SHIR = [0xff, 0xf8, 0xec];
const ZAFARAN = [0xf5, 0xa6, 0x23];
const INK = [0x23, 0x14, 0x09];

/* -------------------------------------------------------------------------- */
/*  PNG encoding                                                              */
/* -------------------------------------------------------------------------- */

const CRC_TABLE = (() => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c;
  }
  return table;
})();

function crc32(buf) {
  let c = -1;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ -1) >>> 0;
}

function chunk(type, data) {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length, 0);
  const body = Buffer.concat([Buffer.from(type, "ascii"), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body), 0);
  return Buffer.concat([length, body, crc]);
}

/**
 * Truecolour 8-bit PNG from a raw RGB buffer.
 *
 * Every scanline uses filter type 1 (Sub — each byte minus the one three to its
 * left). On a smooth horizontal gradient that leaves a run of near-zeroes, so
 * deflate turns a 2.2 MB raw image into tens of kilobytes. Filter 0 on the same
 * data is several times larger.
 */
function encodePng(width, height, rgb) {
  const stride = width * 3;
  const raw = Buffer.alloc((stride + 1) * height);

  for (let y = 0; y < height; y++) {
    const src = y * stride;
    const dst = y * (stride + 1);
    raw[dst] = 1;
    for (let x = 0; x < stride; x++) {
      const left = x >= 3 ? rgb[src + x - 3] : 0;
      raw[dst + 1 + x] = (rgb[src + x] - left) & 0xff;
    }
  }

  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // colour type: truecolour
  // 10–12: compression, filter and interlace methods — all 0, the only values
  // the format defines.

  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

/* -------------------------------------------------------------------------- */
/*  The card                                                                  */
/* -------------------------------------------------------------------------- */

const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
const mix = (a, b, t) => a + (b - a) * t;

/** Smooth 0→1 ramp, used for every soft edge so nothing on the card is aliased. */
function smoothstep(edge0, edge1, x) {
  const t = clamp01((x - edge0) / (edge1 - edge0));
  return t * t * (3 - 2 * t);
}

/** Source-over composite of a straight colour at `alpha` onto `dst`. */
function over(dst, colour, alpha) {
  if (alpha <= 0) return;
  for (let i = 0; i < 3; i++) dst[i] = mix(dst[i], colour[i], alpha);
}

/**
 * Coverage of the brand mark: an eight-pointed star, antialiased across one
 * pixel. The same figure as `src/app/icon.svg` and the same one the `tile`
 * geometry repeats — two squares, one turned forty-five degrees, unioned.
 *
 * Both squares are distance functions rather than polygons, which is what
 * makes this a dozen lines instead of a rasteriser: an axis-aligned square is
 * the set where `max(|dx|,|dy|)` is under the radius, a turned one is the set
 * where `(|dx|+|dy|)/√2` is, and the union of two shapes is the smaller of
 * their two distances.
 */
function star8(x, y, cx, cy, r) {
  const dx = Math.abs(x - cx);
  const dy = Math.abs(y - cy);
  const d = Math.min(Math.max(dx, dy), (dx + dy) / Math.SQRT2);
  return 1 - smoothstep(r - 1, r + 1, d);
}

/**
 * A defocused mass: gaussian falloff from a centre.
 *
 * Deliberately *not* a wide smoothstep, which is what the first version of this
 * card used. A smoothstep reaches exactly zero at a finite radius, and at 8 bits
 * per channel that last contour is a visible ring — this card had one arcing
 * from the top-left corner down to the right edge, from a highlight whose
 * falloff happened to end on screen. A gaussian only ever approaches zero, so
 * there is no radius for the eye to find.
 */
function glow(x, y, cx, cy, sigma) {
  const d2 = (x - cx) ** 2 + (y - cy) ** 2;
  return Math.exp(-d2 / (2 * sigma * sigma));
}

/**
 * Ordered dither, not film grain.
 *
 * A wide gradient at 8 bits per channel bands: a 0.14-alpha white spread over
 * 300px gets about 36 levels, so each one occupies ten pixels and the eye reads
 * the contours as edges. Something has to break that up.
 *
 * The studies use random film grain, and measured here that costs 401 KB at the
 * faintest visible amplitude and 541 KB at theirs, against 95 KB smooth —
 * per-pixel noise is precisely what deflate cannot compress. A 4×4 Bayer matrix
 * does the same job for a fraction of that, because it repeats and deflate is
 * very good at things that repeat.
 */
const BAYER = [
  [0, 8, 2, 10],
  [12, 4, 14, 6],
  [3, 11, 1, 9],
  [15, 7, 13, 5],
];

const rgb = Buffer.alloc(W * H * 3);
const px = [0, 0, 0];

// The brand mark, from src/app/icon.svg: the 32-unit box scaled up and
// centred slightly right of middle, so it sits under the light rather than
// opposite it. In the icon the star's squares are 16 units on a 32 box, so the
// arm half-length is 8 units.
const MARK = { size: 420, cx: 640, cy: 315 };
const scale = MARK.size / 32;

for (let y = 0; y < H; y++) {
  for (let x = 0; x < W; x++) {
    px[0] = SHIR[0];
    px[1] = SHIR[1];
    px[2] = SHIR[2];

    // 1 — the tonal fall, top-right to bottom-left.
    const fall = clamp01((x / W) * 0.55 + (1 - y / H) * 0.45);
    over(px, ZAFARAN, mix(0.14, 0.62, fall));

    // 2 — the defocused mass, with its highlight and its shadow.
    over(px, ZAFARAN, glow(x, y, 250, 470, 330) * 0.55);
    over(px, [255, 255, 255], glow(x, y, 1010, 60, 380) * 0.24);
    over(px, INK, glow(x, y, 120, 690, 330) * 0.12);

    // 3 — the mark, the one crisp thing on the card.
    over(px, INK, star8(x, y, MARK.cx, MARK.cy, 8 * scale));

    // 4 — the light source at 78% / 18%, and the vignette that closes it.
    // Both smooth for the same reason as the masses above: the earlier version
    // ramped white to 52% and then black from 52%, and that kink in the slope
    // is another contour the eye can pick out.
    const u = x / W - 0.78;
    const v = y / H - 0.18;
    const t = Math.hypot(u, v) / 0.88;
    over(px, [255, 255, 255], 0.3 * Math.exp(-((t / 0.42) ** 2)));
    over(px, INK, 0.12 * smoothstep(0.45, 1.2, t));

    const d = (BAYER[y & 3][x & 3] / 16 - 0.5) * 1.6;

    const o = (y * W + x) * 3;
    rgb[o] = clamp01((px[0] + d) / 255) * 255;
    rgb[o + 1] = clamp01((px[1] + d) / 255) * 255;
    rgb[o + 2] = clamp01((px[2] + d) / 255) * 255;
  }
}

const file = join(outDir, "og-card.png");
const png = encodePng(W, H, rgb);
writeFileSync(file, png);
console.log(`generated og-card.png  ${W}×${H}  ${(png.length / 1024).toFixed(0)} KB → public/media/`);
